import { useState } from 'react';
import { loginUser } from './api';
import './login.css';

function Login({ onRegister, onSuccess }) {
    const [showPassword, setShowPassword] = useState(false);
    const [role, setRole] = useState('User');
    const [rememberMe, setRememberMe] = useState(true);
    const [error, setError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    async function handleSubmit(event) {
        event.preventDefault();
        setError('');
        setIsSubmitting(true);
        try {
            const form = event.currentTarget;
            const response = await loginUser({
                email: form.email.value,
                password: form.password.value,
                role,
            });
            onSuccess(response.data.user, rememberMe);
        } catch (submitError) {
            setError(submitError.message);
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <main className="login-page">
            <section className="login-card" aria-labelledby="login-title">
                <h1>{role === 'Admin' ? 'Admin Login' : 'Task Manager'}</h1>
                <p className="subtitle">{role === 'Admin' ? 'Login to manage the application' : 'Login to manage your tasks'}</p>

                <form onSubmit={handleSubmit}>
                    <label htmlFor="email">Email</label>
                    <input id="email" name="email" type="email" placeholder="Enter your email" autoComplete="email" required />

                    <label htmlFor="password">Password</label>
                    <div className="password-box">
                        <input id="password" name="password" type={showPassword ? 'text' : 'password'} placeholder="Enter your password" autoComplete="current-password" required />
                        <button type="button" onClick={() => setShowPassword(!showPassword)}>{showPassword ? 'Hide' : 'Show'}</button>
                    </div>

                    {role !== 'Admin' && (
                        <>
                            <label htmlFor="role">Login as</label>
                            <select id="role" name="role" value={role} onChange={(event) => setRole(event.target.value)}>
                                <option value="User">User</option>
                                <option value="Manager">Manager</option>
                                <option value="Admin">Admin</option>
                            </select>
                        </>
                    )}

                    {role !== 'Admin' && (
                        <label className="remember-label">
                            <input type="checkbox" checked={rememberMe} onChange={(event) => setRememberMe(event.target.checked)} /> Remember me
                        </label>
                    )}

                    {error && <p className="message error-message" role="alert">{error}</p>}
                    <button className="login-button" type="submit" disabled={isSubmitting}>{isSubmitting ? 'Logging in...' : role === 'Admin' ? 'Login as Admin' : `Login as ${role}`}</button>
                </form>

                {role !== 'Admin' && (
                    <p className="register-text">Don&apos;t have an account? <button className="link-button" type="button" onClick={onRegister}>Register here</button></p>
                )}
            </section>
        </main>
    );
}
export default Login;
